mapper.select:
SELECT FROM mes_pro_process_pool_event pool_event LEFT JOIN mes_pro_work_order work_order ON work_order.id = pool_event.work_order_id AND work_order.tenant_id = pool_event.tenant_id AND work_order.deleted = 0
LEFT JOIN mes_pro_process process ON process.id = pool_event.process_id AND process.tenant_id = pool_event.tenant_id AND process.deleted = 0 LEFT JOIN mes_md_workstation workstation ON workstation.id = pool_event.workstation_id AND workstation.tenant_id = pool_event.tenant_id AND workstation.deleted = 0 LEFT JOIN mes_pro_process_pool_pqc_record pqc ON pqc.event_id = pool_event.id AND pqc.tenant_id = pool_event.tenant_id AND pqc.deleted = 0 LEFT JOIN ( SELECT review_copy.tenant_id, review_copy.event_id, COUNT(DISTINCT review_copy.id) AS review_copy_count, MAX(review_copy.review_status) AS review_status, COALESCE(SUM(review_copy_field_stat.field_count), 0) AS field_count FROM mes_pro_process_pool_review_copy review_copy LEFT JOIN ( SELECT tenant_id, review_copy_id, COUNT(1) AS field_count FROM mes_pro_process_pool_review_copy_field WHERE deleted = 0 GROUP BY tenant_id, review_copy_id ) review_copy_field_stat ON review_copy_field_stat.review_copy_id = review_copy.id AND review_copy_field_stat.tenant_id = review_copy.tenant_id WHERE review_copy.deleted = 0 GROUP BY review_copy.tenant_id, review_copy.event_id ) review_copy_summary ON review_copy_summary.event_id = pool_event.id AND review_copy_summary.tenant_id = pool_event.tenant_id
LEFT JOIN ( SELECT tenant_id, event_id, CONCAT('原始记录已修改 ', COUNT(1), ' 次') AS summary FROM mes_pro_process_pool_event_revision WHERE deleted = 0 AND revision_status = 'EFFECTIVE' GROUP BY tenant_id, event_id ) revision_summary ON revision_summary.event_id = pool_event.id AND revision_summary.tenant_id = pool_event.tenant_id WHERE ORDER BY pool_event.server_submit_time ASC, pool_event.id ASC LIMIT #{offset}, #{reqVO.pageSize}

SELECT FROM mes_pro_process_pool_event pool_event LEFT JOIN mes_pro_work_order work_order ON work_order.id = pool_event.work_order_id AND work_order.tenant_id = pool_event.tenant_id AND work_order.deleted = 0
LEFT JOIN mes_pro_process process ON process.id = pool_event.process_id AND process.tenant_id = pool_event.tenant_id AND process.deleted = 0 LEFT JOIN mes_md_workstation workstation ON workstation.id = pool_event.workstation_id AND workstation.tenant_id = pool_event.tenant_id AND workstation.deleted = 0 LEFT JOIN mes_pro_process_pool_pqc_record pqc ON pqc.event_id = pool_event.id AND pqc.tenant_id = pool_event.tenant_id AND pqc.deleted = 0 LEFT JOIN ( SELECT review_copy.tenant_id, review_copy.event_id, COUNT(DISTINCT review_copy.id) AS review_copy_count, MAX(review_copy.review_status) AS review_status, COALESCE(SUM(review_copy_field_stat.field_count), 0) AS field_count FROM mes_pro_process_pool_review_copy review_copy LEFT JOIN ( SELECT tenant_id, review_copy_id, COUNT(1) AS field_count FROM mes_pro_process_pool_review_copy_field WHERE deleted = 0 GROUP BY tenant_id, review_copy_id ) review_copy_field_stat ON review_copy_field_stat.review_copy_id = review_copy.id AND review_copy_field_stat.tenant_id = review_copy.tenant_id WHERE review_copy.deleted = 0 GROUP BY review_copy.tenant_id, review_copy.event_id ) review_copy_summary ON review_copy_summary.event_id = pool_event.id AND review_copy_summary.tenant_id = pool_event.tenant_id
LEFT JOIN ( SELECT tenant_id, event_id, CONCAT('原始记录已修改 ', COUNT(1), ' 次') AS summary FROM mes_pro_process_pool_event_revision WHERE deleted = 0 AND revision_status = 'EFFECTIVE' GROUP BY tenant_id, event_id ) revision_summary ON revision_summary.event_id = pool_event.id AND revision_summary.tenant_id = pool_event.tenant_id WHERE pool_event.deleted = 0 AND pool_event.id = #{id}
